structure.mermaidSource:
flowchart TD
  start["Início: Delimitação Estrutural [...]"] --> dec_morfo{"Qual a classe morfológica do núcleo?"}
  dec_morfo -- "Adjetivo" --> res_predicativo["NÃO É APOSTO: Predicativo Deslocado (valor atributivo)"]
  dec_morfo -- "Substantivo / Pronome" --> proc_extracao["Extrair Núcleo: Identificar palavra-base não preposicionada"]
  proc_extracao --> dec_explicativo{"Explica termo antecedente entre pausas?"}
  dec_explicativo -- "Sim" --> res_explicativo["Aposto Explicativo (vírgulas, travessões ou parênteses)"]
  dec_explicativo -- "Não" --> dec_enumerativo{"Desdobra antecedente em lista/enumeração?"}
  dec_enumerativo -- "Sim" --> res_enumerativo["Aposto Enumerativo (desdobramento em partes ordenadas)"]
  dec_enumerativo -- "Não" --> dec_distributivo{"Distribui termos em pares simétricos correlatos?"}
  dec_distributivo -- "Sim" --> res_distributivo["Aposto Distributivo (pares um/outro, este/aquele)"]
  dec_distributivo -- "Não" --> dec_resumitivo{"Sintetiza termos anteriores por pronome indefinido?"}
  dec_resumitivo -- "Sim" --> res_resumitivo["Aposto Resumitivo/Recapitulativo (tudo, nada; atrai verbo singular)"]
  dec_resumitivo -- "Não" --> dec_especificativo{"Nome próprio que individualiza termo comum sem vírgulas?"}
  dec_especificativo -- "Sim" --> res_especificativo["Aposto Especificativo (sem pausas: o poeta Drummond)"]
  dec_especificativo -- "Não" --> dec_oracional{"Sintetiza uma oração inteira (substantivo / pronome 'o')?"}
  dec_oracional -- "Sim" --> res_oracional["Aposto em Referência a Oração (fato que, coisa que)"]
  dec_oracional -- "Não" --> res_outro_termo["Não é Aposto: Reavaliar função sintática (Adjunto, Complemento, etc.)"]
